import { copyFileSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

// Failure modes were listed in docs/process/upstream-0.14.0-assessment.md before this probe.
// Commands below are data passed to permission checks. They are never executed.
const auditRoot = resolve('.git/upstream-0140-audit')
const configRoot = join(auditRoot, 'config')
const workspaceRoot = join(auditRoot, 'workspace')
mkdirSync(join(configRoot, 'permissions'), { recursive: true })
mkdirSync(workspaceRoot, { recursive: true })
copyFileSync('apps/electron/resources/permissions/default.json', join(configRoot, 'permissions/default.json'))
process.env.PHANERIS_CONFIG_DIR = configRoot
process.env.NODE_ENV = 'test'

const { shouldAllowToolInMode, setPermissionMode } = await import('../../packages/shared/src/agent/mode-manager.ts')
const { shouldPromptInAskMode } = await import('../../packages/shared/src/agent/core/pre-tool-use.ts')
const { PermissionManager } = await import('../../packages/shared/src/agent/core/permission-manager.ts')
const { PiAgent } = await import('../../packages/shared/src/agent/pi-agent.ts')
const { SessionManager } = await import('../../packages/server-core/src/sessions/SessionManager.ts')
const storage = await import('../../packages/shared/src/sessions/storage.ts')
const context = { workspaceRootPath: workspaceRoot, activeSourceSlugs: ['demo', 'budget'] }
const rows: Array<Record<string, unknown>> = []

for (const [command, expected] of [
  ['gh api /repos/example/project -X DELETE', false],
  ['gh api /repos/example/project -f title=x', false],
  ["sed -n -i '1p' fixture.txt", false],
  ["sed -n 'w output.txt' fixture.txt", false],
  ['sort -o output.txt fixture.txt', false],
  ['find . -delete', false],
  ['gh api /repos/example/project -X GET', true],
  ["sed -n '1p' fixture.txt", true],
  ['sort fixture.txt', true],
] as const) {
  const actual = shouldAllowToolInMode('Bash', { command }, 'safe', { permissionsContext: context })
  rows.push({ id: 'safe-bash', input: command, expected_allowed: expected, actual_allowed: actual.allowed, matches_expected: actual.allowed === expected })
}

for (const [tool, expected] of [
  ['mcp__demo__delete_account', false],
  ['mcp__demo__send_thread_reply', false],
  ['mcp__demo__update_spreadsheet', false],
  ['mcp__budget__create_issue', false],
  ['mcp__demo__list_items', true],
] as const) {
  const actual = shouldAllowToolInMode(tool, {}, 'safe', { permissionsContext: context })
  rows.push({ id: 'safe-mcp', input: tool, expected_allowed: expected, actual_allowed: actual.allowed, matches_expected: actual.allowed === expected })
}

const sessionId = 'upstream0140-probe'
const pm = new PermissionManager({ sessionId })
setPermissionMode(sessionId, 'ask', { changedBy: 'restore' })
const listPrompt = shouldPromptInAskMode('mcp__demo__list_items', {}, pm, context)
rows.push({ id: 'ask-readonly-mcp', expected_prompt: false, actual_prompt: listPrompt !== null, prompt_type: listPrompt?.promptType, matches_expected: listPrompt === null })

let resolved: boolean | undefined
const responseAgent = Object.create(PiAgent.prototype) as any
responseAgent.permissionManager = pm
responseAgent.pendingPermissions = new Map([['remember-probe', { toolName: 'Bash', resolve: (value: boolean) => { resolved = value } }]])
responseAgent.respondToPermission('remember-probe', true, true)
const afterAlwaysAllow = shouldPromptInAskMode('Bash', { command: 'git commit -m audit' }, pm, context)
rows.push({ id: 'pi-always-allow', current_allowed: resolved, expected_next_prompt: false, actual_next_prompt: afterAlwaysAllow !== null, matches_expected: afterAlwaysAllow === null })

// This is deliberately a synthetic old-style whitelist. Pi currently never populates it.
pm.whitelistCommand('git')
for (const command of ['git push --force', 'git reset --hard', 'git commit -m audit && rm -rf ~/never-executed']) {
  const prompt = shouldPromptInAskMode('Bash', { command }, pm, context)
  rows.push({ id: 'legacy-whitelist-conditional', synthetic_whitelist: 'git', input: command, expected_prompt: true, actual_prompt: prompt !== null, matches_expected: prompt !== null })
}

function fakePermissionAgent(active: boolean, handler: boolean) {
  const id = `upstream0140-pi-${active}-${handler}`
  setPermissionMode(id, 'ask', { changedBy: 'restore' })
  const agent = Object.create(PiAgent.prototype) as any
  const activeSlugs = new Set<string>(active ? ['demo'] : [])
  const responses: Array<Record<string, unknown>> = []
  const prompts: Array<Record<string, unknown>> = []
  agent.config = { workspace: { rootPath: workspaceRoot, id: 'probe' }, session: { id, workingDirectory: workspaceRoot } }
  agent._sessionId = id
  agent.workingDirectory = workspaceRoot
  agent.debug = () => {}
  agent.emitAutomationEvent = async () => {}
  agent.sourceManager = { getActiveSlugs: () => activeSlugs, getAllSources: () => [{ config: { slug: 'demo' } }] }
  agent.permissionManager = new PermissionManager({ sessionId: id })
  agent.prerequisiteManager = { checkPrerequisites: () => ({ allowed: true }), trackBashSkillRead: () => false }
  agent.onSourceActivationRequest = async () => { activeSlugs.add('demo'); return true }
  agent.onPermissionRequest = handler ? (request: Record<string, unknown>) => { prompts.push(request) } : null
  agent.getCurrentTurnUserMessage = () => 'audit'
  agent.eventQueue = { enqueue: () => {} }
  agent.send = (response: Record<string, unknown>) => { responses.push(response) }
  agent.pendingPermissions = new Map()
  return { agent, responses, prompts }
}
const activation = fakePermissionAgent(false, true)
await activation.agent.handlePreToolUseRequest({ requestId: 'activation-probe', toolName: 'mcp__demo__create_issue', input: {} })
rows.push({ id: 'pi-activation-permission', expected: 'prompt', actual: activation.responses.at(-1)?.action, prompts: activation.prompts.length, matches_expected: activation.prompts.length === 1 })
const noHandler = fakePermissionAgent(true, false)
await noHandler.agent.handlePreToolUseRequest({ requestId: 'no-handler-probe', toolName: 'Bash', input: { command: 'touch audit-fixture.txt' } })
rows.push({ id: 'pi-no-permission-handler', expected: 'block', actual: noHandler.responses.at(-1)?.action, matches_expected: noHandler.responses.at(-1)?.action === 'block' })

const manager = Object.create(SessionManager.prototype) as any
let first = 0
let resubscribed = 0
const nextListener = () => { resubscribed++ }
const firstListener = () => {
  first++
  manager.sessionCompletionListeners.delete(firstListener)
  manager.sessionCompletionListeners.add(nextListener)
}
manager.sessionCompletionListeners = new Set([firstListener])
manager.emitSessionComplete({ sessionId: 'probe', reason: 'complete' })
rows.push({ id: 'completion-listener-resubscribe', first_calls: first, expected_new_listener_calls: 0, actual_new_listener_calls: resubscribed, matches_expected: resubscribed === 0 })

const session = await storage.createSession(workspaceRoot, { name: 'upstream audit fixture' })
const sessionFile = storage.getSessionFilePath(workspaceRoot, session.id)
const before = statSync(sessionFile, { bigint: true })
await new Promise(resolve => setTimeout(resolve, 30))
await storage.clearPendingPlanExecution(workspaceRoot, session.id)
const after = statSync(sessionFile, { bigint: true })
rows.push({ id: 'clear-no-pending-plan', expected_file_rewritten: false, actual_file_rewritten: before.mtimeNs !== after.mtimeNs, matches_expected: before.mtimeNs === after.mtimeNs })

const reportPath = 'docs/verification/results/upstream-0.14.0-assessment.json'
const report = JSON.parse(readFileSync(reportPath, 'utf8'))
report.probes = { executed_at: new Date().toISOString(), execution: 'bun .git/upstream-0140-audit/probes.ts', config_root: configRoot, workspace_root: workspaceRoot, limitation: 'Existing code paths driven with isolated callbacks; no commands, real provider calls, GUI E2E, or source migrations executed.', total: rows.length, gaps: rows.filter(r => !r.matches_expected).length, rows }
writeFileSync(reportPath, JSON.stringify(report, null, 2) + '\n')
console.log(JSON.stringify(report.probes, null, 2))

