import { readFileSync,writeFileSync } from 'node:fs';
import { getBashRememberKey } from './upstream-permission-remember.ts';
import { PermissionManager } from '../../packages/shared/src/agent/core/permission-manager.ts';
const first = getBashRememberKey('python Safe.py');
const second = getBashRememberKey('python safe.py');
const manager = new PermissionManager({sessionId:'case-probe'});
manager.whitelistCommand(first!);
const path='docs/verification/results/upstream-0.14.0-assessment.json';
const report=JSON.parse(readFileSync(path,'utf8'));
report.upstream_probes={executed_at:new Date().toISOString(),source:'73bd9c2a',note:'Upstream key builder, imports redirected to isolated fixture; whitelist store is byte-for-byte identical in its case normalization to upstream.',rows:[{id:'exact-argv-casefold',first,second,builder_keys_differ:first!==second,store_matches_other_key:manager.isCommandWhitelisted(second!),expected_other_key_match:false}]};
writeFileSync(path,JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report.upstream_probes,null,2));
